/// The feature levels the C# `D3D11.CreateDevice` offers, in this order: 11.0, 10.1, 10.0, 9.3 (no 11.1: the C# list is kept).
pub const FEATURE_LEVELS: [D3D_FEATURE_LEVEL; 4] = [
    D3D_FEATURE_LEVEL_11_0,
    D3D_FEATURE_LEVEL_10_1,
    D3D_FEATURE_LEVEL_10_0,
    D3D_FEATURE_LEVEL_9_3,
];

/// `D3D11_CREATE_DEVICE_BGRA_SUPPORT` (0x20), the only flag the renderer sets (C# `D3D11Constants.CreateDeviceBgraSupport`).
/// The device is NOT created single-threaded (C# never passed `CreateDeviceSingleThreaded`).
pub const DEFAULT_DEVICE_FLAGS: D3D11_CREATE_DEVICE_FLAG = D3D11_CREATE_DEVICE_BGRA_SUPPORT;

/// Which driver `D3D11CreateDevice` is asked for (C# `D3DDriverType`, of which only these two are ever used).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum DriverKind {
    /// `D3D_DRIVER_TYPE_HARDWARE` with no adapter (the default adapter).
    Hardware,
    /// `D3D_DRIVER_TYPE_WARP`, the CPU rasterizer (no GPU, RDP, CI, tests).
    Warp,
}

/// A created device and what the caller needs to know about it.
#[derive(Debug, Clone)]
pub struct CreatedDevice {
    /// The Direct3D 11 device (the immediate context is not kept: Direct2D manages it, C# passed a NULL context).
    pub device: ID3D11Device,
    /// The feature level the driver granted (`0xb000` for 11.0).
    pub feature_level: D3D_FEATURE_LEVEL,
    /// `true` for [`DriverKind::Warp`].
    pub is_warp: bool,
}

